insert into expressions (id,waray,translation) values
  (20001,'Pilipino ka.','You are a Filipino.'),
  (20002,'Amerikano ako.','I am an American.'),
  (20003,'Estudyante hiya.','He/She is a student.'),
  (20004,'Mahusay hiya.','She is beautiful.'),
  (20005,'Hataas ako.','I am tall.'),
  (20006,'Riko hira.','They are rich.'),
  (20007,'Mga lalake kita.','We (incl) are men (male).'),
  (20008,'Mga babaye kami.','We (excl) are women (female).'),
  (20009,'Mga sangkay kita.','We (incl) are friends.'),
  (20010,'Mga Pilipino kami.','We (excl) are Filipinos.'),
  (20011,'Ako hi Peter.','I am Peter.'),
  (20012,'Hiya hi Bebing.','She is Bebing.'),
  (20013,'Pilipino hi Pablo.','Pablo is Filipino.'),
  (20014,'Hira Perla ngan Tessie.','They are Perla and Tessie.'),
  (20015,'Buotan hi Ernesto.','Ernesto is nice.'),
  (20016,'Riko hira Marvin ngan Annie.','Marvin and Annie are rich.'),
  (20017,'Mahusay an lamesa.','The table is beautiful.'),
  (20018,'Mabusag an papel.','The paper is white.'),
  (20019,'Malabad an mga bata.','The children are naughty.'),
  (20020,'Madig-on an mga lingkuran.','The chairs are strong.'),
  (20021,'Mahuram an panday hin saruwal para ha iya apoy.','The carpenter will borrow trousers for his/her grandparent.'),
  (20022,'Pinmalit hi Lorie hin prutas dida ha tindahan para ha pamilya niya.','Lorie bought fruit there at the store for her family.'),
  (20023,'Kinmaon kita hiton nga mangga didto ha balay niyo.','We ate that mango there at your (pl) house.'),
  (20024,'Sinmimba an mga tawo didto ha mga diyos-diyos.','The people worshipped there at the idols.'),
  (20025,'Mahangyo hiya hin pabor dinhi para kan Tessie.','He/She will ask for a favor here for Tessie.'),
  (20026,'Mahuram hiya hini nga kwarta para ha iyo pamilya.','He will borrow this money for your family.'),
  (20027,'Nagdara kami hin bukad didto para kan Alma.','We brought flowers there for Alma.'),
  (20028,'Nakaon an doktor hin tinapay didto ha tindahan.','The doctor is eating bread there (far) at the store.'),
  (20029,'Sinmaka hira didto ha balay ni Luz.','They climbed up there at Luz''s house.'),
  (20030,'Masugat ako han akon sangkay didto ha Gaisano.','I will catch up with my friend there (far) at Gaisano.'),
  (20031,'Akon ini nga balay.','This house is mine.'),
  (20032,'Imo an libro.','The book is yours (sing).'),
  (20033,'Iya an sapatos.','The shoes are his/hers.'),
  (20034,'Aton ini nga eskwelahan.','This school is ours (incl).'),
  (20035,'Amon an ayam.','The dog is ours (excl).'),
  (20036,'Iyo ini nga tsinelas.','These slippers are yours (pl).'),
  (20037,'Ira an sinehan.','The movie house is theirs.'),
  (20038,'Aton ini nga nasud.','This country is ours (incl).'),
  (20039,'Iya ini nga uma.','This farm is his.'),
  (20040,'Akon ini nga bata.','This baby is mine.'),
  (20041,'Inminom an akon uyab hin kape.','My boyfriend/girlfriend drank coffee.'),
  (20042,'Dinmala ako ha imo bag.','I brought your bag.'),
  (20043,'Peligroso an iya gugma.','His love is dangerous.'),
  (20044,'Adto an aton simbahan.','That (far) is our (incl) church.'),
  (20045,'Hinmulam hi Rico ha ámòn telebisyon.','Rico borrowed our television.'),
  (20046,'Makuyog hira Tata ngan Alex ha ịyo nga biyahe.','Tata and Alex will accompany (you) on your trip.'),
  (20047,'Maduroto an mga miyembro ha íra nga iglesiya.','The members of their church are industrious.'),
  (20048,'Imo ini nga gatas.','This milk is yours (sing).'),
  (20049,'Akon adto nga tsinelas.','That (far) slipper is mine.'),
  (20050,'Aton ini nga manok.','This chicken is ours (incl).'),
  (20051,'Kinmadto ako ha akon uma.','I went to my farm.'),
  (20052,'Binmisita hi Terso ha ịyo simbahan.','Terso visited your (pl) church.'),
  (20053,'Naupod an mga estudyante ha íra maestra.','The students accompanied their teacher.'),
  (20054,'Makaon ka han ámòn pagkaon.','You will eat our (excl) food.'),
  (20055,'Masugat hi Lucy han iya ayam didto ha siyudad.','Lucy will meet her dog there in the city.'),
  (20056,'Nahangyo hira hin pabor ha imo tatay.','They asked for a favor from your (sing) father.'),
  (20057,'Binmasa hi Rose han akon libro dida ha sala.','Rose read my book there in the living room.'),
  (20058,'Nakatawa hira ha imo nawong.','They laughed at your face.'),
  (20059,'Mahigda an akon anak ha imo katre.','My child will lay down (is going to lay down) on your bed.'),
  (20060,'Mapalit an akon maestra hini nga telebisyon para ha imo asawa.','My teacher will buy this television for your wife.'),
  (20061,'Inminom an mga panday hin kape didto ha íra balay.','The carpenters drank coffee there (far) at their house.'),
  (20062,'Ịyo ini nga leksyon.','This lesson is yours (pl).'),
  (20063,'Íra adto nga lamesa ngan lingkuranan.','That table and chair is theirs.'),
  (20064,'Kinmarawat hira kan Kristo ha íra kasingkásing.','They accepted Christ in (into) their hearts.'),
  (20065,'Matutdo hi Pastor Tan han Bibliya didto ha ịyo simbahan.','Pastor Tan will teach the Bible there (far) in your (pl) church.'),
  (20066,'Makanta an mga Kristiyano didto ha balay han áton kaharani.','The Christians will sing there at the house of our (pl) neighbors.'),
  (20067,'Nagdara an mga bisita hin pagkaon dinhi ha ámòn balay para ha Kaádlawan ni Ashley.','The visitors brought food (pl) here in our (pl) house for Ashley''s birthday.'),
  (20068,'Ira adto nga balay.','Their house over there.'),
  (20069,'Nadara hi Rose ha amon mga bado didto ha ira balay.','Rose brought our (excl) clothes there to their house.'),
  (20070,'Mabalhin an ira kaamyaw didto ha ira uma.','Their relatives will move there to their farm.'),
  (20071,'Iyo iton mga kabulig ha tindahan.','Those helpers in the store are yours (pl).'),
  (20072,'Pinmalit hiya hiton nga mangga dida ha imo sangkay.','He bought that mango from your (sing) friend.'),
  (20073,'Nanghuram an nars hin lapis ha iya nanay.','The nurse borrowed a pencil from her mother.'),
  (20074,'Aton ini nga mga bisita.','These visitors are ours (incl).'),
  (20075,'Upda an imo lola didto ha syudad.','Accompany (go with) your grandmother there (far) to the city.'),
  (20076,'Nahigda an iyo mga anak ha katre ni Katrina.','Your (pl) children laid down on Katrina''s bed.'),
  (20077,'Akon an pinirito nga manok.','The fried chicken is mine.'),
  (20078,'Matan-aw hiya ha akon.','He will look at me.'),
  (20079,'Makadto ako ha imo balay.','I will go to your house.'),
  (20080,'Hinmatag hi Perlita hin bola ha iya.','Perlita gave a ball to him.'),
  (20081,'Mabasa an akon anak hini nga libro ha amon.','My child will read this book to us (excl).'),
  (20082,'Nakanta hi Liling ha iyo.','Liling is singing to you (pl).'),
  (20083,'Pinmalit ako hin saging ha ira tindahan.','I bought banana at their store.'),
  (20084,'Pinmalit ako hin saging para ha ira.','I bought banana for them.'),
  (20085,'Mahuram hiya hin kwarta ha akon.','He will borrow money from me.'),
  (20086,'Maabot an iya bugto ha amon.','His/Her sibling will arrive to us (excl).'),
  (20087,'Mabisita hira Jun ngan Romy ha aton dinhi ha Davao.','Jun and Romy will visit us (incl) here in Davao.'),
  (20088,'Sinmurat an akon lolo ha ira didto ha states.','My grandfather wrote to them there in the states.'),
  (20089,'Naupod an amon anak ha ira.','Our (excl) child is going with them.'),
  (20090,'Daku an gugma ha Diyos para ha aton.','Great is God''s love for us (incl).'),
  (20091,'Mapipili ako ha ira.','I will choose from them.'),
  (20092,'Mahuhugasan an amon mga kabulig hin bado para ha iyo.','Our helpers will wash clothes for you (pl).'),
  (20093,'Makadto hi Alex ha iyo balay.','Alex will go to your (pl) house.'),
  (20094,'Masarig kita ha Iya, ngan mahatag Hiya hin bendisyon ha aton.','We will trust Him, and He will give a blessing to us (incl).'),
  (20095,'Mabalhin hira Jane ngan John ha amon balay.','Jane and John are moving to our (excl) house.'),
  (20096,'Kinmanta an uyab ni Lorie ha iya.','Lorie''s boyfriend sang to her.'),
  (20097,'Nagwali an pastor ha ira didto ha ira lugar.','The pastor preached to them there at their place.'),
  (20098,'Pinmalit an doktor hin saging ha amon tindahan.','The doctor bought bananas at our (excl) store.'),
  (20099,'Maampo an Pastor para ha akon ngan ha akon pamilya.','The Pastor will pray for me and my family.'),
  (20100,'Naupod ako ha iya.','I''m following with him.') on conflict (id) do nothing;
